export default function Portfolio() {
  const [menuOpen, setMenuOpen] = useState(false);
  const [scrolled, setScrolled] = useState(false);
  const [activeId, setActiveId] = useState("home");

  useEffect(() => {
    const onScroll = () => setScrolled(window.scrollY > 40);
    onScroll();
    window.addEventListener("scroll", onScroll, { passive: true });
    return () => window.removeEventListener("scroll", onScroll);
  }, []);

  useEffect(() => {
    const ids = NAV_LINKS.map((l) => l.id);
    const obs = new IntersectionObserver(
      (entries) => {
        entries.forEach((entry) => {
          if (entry.isIntersecting) setActiveId(entry.target.id);
        });
      },
      { rootMargin: "-40% 0px -50% 0px", threshold: 0 }
    );
    ids.forEach((id) => {
      const el = document.getElementById(id);
      if (el) obs.observe(el);
    });
    return () => obs.disconnect();
  }, []);

  const scrollTo = useCallback((id) => {
    setMenuOpen(false);
    const el = document.getElementById(id);
    if (el) el.scrollIntoView({ behavior: "smooth", block: "start" });
  }, []);

  return (
    <div className="portfolio-root bg-base min-h-screen relative">
      <style>{`
        @import url('https://fonts.googleapis.com/css2?family=Space+Grotesk:wght@500;600;700&family=Inter:wght@400;500;600;700&family=IBM+Plex+Mono:wght@400;500;600&display=swap');

        .portfolio-root {
          --bg: #0A0E16;
          --surface: #121828;
          --line: #232B40;
          --paper: #EDEFF4;
          --dust: #8B94AC;
          --signal: #4C7EFF;
          --signal-dim: rgba(76,126,255,0.14);
          --warm: #FF9166;
          --warm-dim: rgba(255,145,102,0.14);
          font-family: 'Inter', sans-serif;
          color: var(--paper);
          isolation: isolate;
        }
        .portfolio-root::before {
          content: "";
          position: fixed;
          inset: 0;
          pointer-events: none;
          z-index: 0;
          background-image:
            linear-gradient(var(--line) 1px, transparent 1px),
            linear-gradient(90deg, var(--line) 1px, transparent 1px);
          background-size: 48px 48px;
          opacity: 0.035;
        }
        .portfolio-root > * { position: relative; z-index: 1; }

        .bg-base { background: var(--bg); }
        .section-tint { background: rgba(18,24,40,0.3); }
        .text-paper { color: var(--paper); }
        .text-dust { color: var(--dust); }
        .text-signal { color: var(--signal); }
        .text-warm { color: var(--warm); }
        .bg-signal { background: var(--signal); }
        .bg-warm { background: var(--warm); }
        .border-hair { border-color: var(--line); }
        .border-warm { border-color: var(--warm) !important; }
        .font-display { font-family: 'Space Grotesk', sans-serif; }
        .font-mono { font-family: 'IBM Plex Mono', monospace; }

        .nav-glass { background: rgba(10,14,22,0.78); backdrop-filter: blur(14px); -webkit-backdrop-filter: blur(14px); }

        .card { background: var(--surface); border: 1px solid var(--line); border-radius: 1rem; }
        .card-hover { transition: transform .3s ease, border-color .3s ease, box-shadow .3s ease; }
        .card-hover:hover { transform: translateY(-4px); border-color: var(--signal); box-shadow: 0 20px 40px -20px rgba(76,126,255,0.35); }
        .card-ghost { background: transparent; border: 1px dashed var(--line); }

        .chip {
          display: inline-block; padding: 0.35rem 0.75rem; border: 1px solid var(--line);
          border-radius: 999px; font-family: 'IBM Plex Mono', monospace; font-size: 0.75rem;
          color: var(--dust); background: rgba(255,255,255,0.02);
        }
        .placeholder-pill { display: inline-flex; padding: 0.3rem 0.65rem; border: 1px dashed var(--dust); border-radius: 999px; color: var(--dust); }

        .photo-frame {
          position: relative; width: 100%; overflow: hidden; border-radius: 1.25rem;
          border: 1px solid var(--line);
          box-shadow: 0 24px 48px -24px rgba(0,0,0,0.55);
          transition: transform .4s ease, box-shadow .4s ease, border-color .4s ease;
        }
        .photo-frame img { width: 100%; height: 100%; object-fit: cover; display: block; }
        .photo-frame:hover { transform: translateY(-4px); box-shadow: 0 32px 64px -20px rgba(76,126,255,0.3); border-color: var(--signal); }
        .photo-frame-warm:hover { box-shadow: 0 32px 64px -20px rgba(255,145,102,0.35); border-color: var(--warm); }
        .photo-overlay {
          position: absolute; inset: 0; pointer-events: none;
          background: linear-gradient(to top, rgba(10,14,22,0.32), transparent 45%);
        }
        .photo-caption {
          font-family: 'IBM Plex Mono', monospace; font-size: 0.7rem; letter-spacing: 0.08em;
          text-transform: uppercase; color: var(--dust); margin-top: 0.85rem; text-align: left;
        }

        .btn-primary {
          display: inline-flex; align-items: center; gap: 0.5rem; padding: 0.65rem 1.15rem;
          background: var(--signal); color: #06090f; font-weight: 600; font-size: 0.875rem;
          border-radius: 999px; border: none; cursor: pointer;
          transition: transform .2s ease, box-shadow .2s ease;
        }
        .btn-primary:hover { transform: translateY(-2px); box-shadow: 0 10px 24px -8px rgba(76,126,255,0.55); }

        .btn-ghost {
          display: inline-flex; align-items: center; gap: 0.5rem; padding: 0.65rem 1.15rem;
          background: transparent; color: var(--paper); font-weight: 500; font-size: 0.875rem;
          border-radius: 999px; border: 1px solid var(--line); cursor: pointer;
          transition: border-color .2s ease, transform .2s ease;
        }
        .btn-ghost:hover { border-color: var(--signal); color: var(--signal); transform: translateY(-2px); }

        a, button { text-decoration: none; }
        :focus-visible { outline: 2px solid var(--signal); outline-offset: 3px; border-radius: 4px; }

        .reveal { opacity: 0; transform: translateY(24px); transition: opacity .7s ease, transform .7s ease; }
        .reveal.is-visible { opacity: 1; transform: none; }

        .hero-line { opacity: 0; transform: translateY(16px); animation: heroIn .7s ease forwards; }
        @keyframes heroIn { to { opacity: 1; transform: none; } }

        .timeline-line { position: absolute; left: 3px; top: 8px; bottom: 8px; width: 1px; background: var(--line); }
        .timeline-dot {
          position: absolute; left: -29px; top: 6px; width: 8px; height: 8px; border-radius: 999px;
          background: var(--signal); box-shadow: 0 0 0 4px var(--signal-dim);
        }
        .timeline-dot-open {
          background: transparent; border: 2px dashed var(--warm); box-shadow: 0 0 0 4px var(--warm-dim);
          width: 10px; height: 10px; left: -30px;
        }

        .few-thing {
          display: flex; gap: 1rem; align-items: baseline; padding: 1.1rem 0;
          border-bottom: 1px solid var(--line); font-family: 'Space Grotesk', sans-serif;
          font-size: 1.15rem; color: var(--paper);
        }
        .few-thing:last-child { border-bottom: none; }
        .few-thing-mark { color: var(--warm); font-family: 'IBM Plex Mono', monospace; }

        @media (prefers-reduced-motion: reduce) {
          .reveal, .hero-line { opacity: 1 !important; transform: none !important; animation: none !important; transition: none !important; }
        }
      `}</style>

      <NavBar activeId={activeId} scrolled={scrolled} menuOpen={menuOpen} setMenuOpen={setMenuOpen} scrollTo={scrollTo} />

      <main>
        <Hero scrollTo={scrollTo} />
        <SnapshotSection />
        <JourneySection />
        <InterestsSection />
        <FewThingsSection />
        <HockeySection />
        <OutsideClassroomSection />
        <BuildingSection />
        <ChaptersSection />
        <AchievementsSection />
        <StillBecomingSection />
        <ConnectSection />
      </main>

      <Footer />
    </div>
  );
}
